17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    /** Dedicated audit trail logger; carries a line for each successful owner create. */
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    /** HTTP header carrying the caller-supplied idempotency key for create requests. */
60	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
61	
62	    /**
63	     * Remembers the owner created for each already-seen {@code Idempotency-Key}, so a repeated create
64	     * with the same key returns the originally created owner instead of creating a duplicate. Keyed by
65	     * the header value, valued by the created owner's id.
66	     */
67	    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotentCreates =
68	        new java.util.concurrent.ConcurrentHashMap<>();
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
114	     *  separated by '@', none of which contain whitespace or a second '@'. */
115	    private static final java.util.regex.Pattern EMAIL_PATTERN =
116	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
117	
118	    /** Disposable email domains that are not accepted as an owner's email. */
119	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
120	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
121	
122	    /**
123	     * Normalize the optional email: absent stays absent; when present it must be syntactically
124	     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
125	     * domain is on the disposable-domain blocklist.
126	     */
127	    private boolean normalizeEmail(Owner owner) {
128	        String email = owner.getEmail();
129	        if (email == null || email.isEmpty()) {
130	            owner.setEmail(null);
131	            return true;
132	        }
133	        if (!EMAIL_PATTERN.matcher(email).matches()) {
134	            return false;
135	        }
136	        email = email.toLowerCase(java.util.Locale.ROOT);
137	        String domain = email.substring(email.indexOf('@') + 1);
138	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
139	            return false;
140	        }
141	        owner.setEmail(email);
142	        return true;
143	    }
144	
145	    /**
146	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
147	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
148	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
149	     *
150	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
151	     *         a valid E.164 number.
152	     */
153	    private static String toE164(String raw) {
154	        if (raw == null) {
155	            return null;
156	        }
157	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
158	        String digits;
159	        if (cleaned.startsWith("+")) {
160	            digits = cleaned.substring(1);
161	        } else {
162	            if (cleaned.startsWith("0")) {
163	                cleaned = cleaned.substring(1);
164	            }
165	            digits = "61" + cleaned;
166	        }
167	        if (!digits.matches("\\d{8,15}")) {
168	            return null;
169	        }
170	        return "+" + digits;
171	    }
172	
173	    /**
174	     * Validate the national-number length of a canonical E.164 string against its country code:
175	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
176	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
177	     * string produced by {@link #toE164}.
178	     *
179	     * @return {@code true} when the national-number length is correct for the country code.
180	     */
181	    private static boolean hasValidNationalLength(String e164) {
182	        String digits = e164.substring(1);
183	        if (digits.startsWith("61")) {
184	            return digits.length() - 2 == 9;
185	        }
186	        if (digits.startsWith("1")) {
187	            return digits.length() - 1 == 10;
188	        }
189	        return true;
190	    }
191	
192	    /**
193	     * Build the customer code {@code <REGION>-<HASH8>}: REGION is the region code derived from the
194	     * owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no known
195	     * range) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the concatenation of
196	     * the owner's normalized (E.164) telephone and last name (e.g. {@code NSW-3F9A0C17}). No sequence
197	     * numbers are used, so the base code is a pure function of the owner's region-and-hash identity.
198	     * When that base code collides with an existing owner's customerCode, {@code -<n>} is appended with
199	     * the smallest {@code n} of 2 or more that makes it unique, returning the de-duplicated code.
200	     */
201	    private String customerCodeFor(Owner owner) {
202	        String region = ownerMapper.regionFromPostcode(owner);
203	        if (region == null) {
204	            region = "UNKNOWN";
205	        }
206	        String base = region + "-" + hash8(owner.getTelephone(), owner.getLastName());
207	
208	        java.util.Set<String> existingCodes = new java.util.HashSet<>();
209	        for (Owner existing : this.clinicService.findAllOwners()) {
210	            String code = existing.getCustomerCode();
211	            if (code != null) {
212	                existingCodes.add(code);
213	            }
214	        }
215	        if (!existingCodes.contains(base)) {
216	            return base;
217	        }
218	        for (int n = 2; ; n++) {
219	            String candidate = base + "-" + n;
220	            if (!existingCodes.contains(candidate)) {
221	                return candidate;
222	            }
223	        }
224	    }
225	
226	    /**
227	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
228	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
229	     */
230	    private static String hash8(String normalizedTelephone, String lastName) {
231	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
232	            + (lastName == null ? "" : lastName);
233	        try {
234	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
235	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
236	            StringBuilder sb = new StringBuilder(8);
237	            for (int i = 0; i < 4; i++) {
238	                sb.append(String.format("%02X", digest[i]));
239	            }
240	            return sb.toString();
241	        }
242	        catch (java.security.NoSuchAlgorithmException e) {
243	            throw new IllegalStateException(e);
244	        }
245	    }
246	
247	    /** Common street-type abbreviations expanded during address normalization. */
248	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
249	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
250	
251	    /**
252	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
253	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
254	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
255	     */
256	    private static String normalizeAddress(String value) {
257	        if (value == null) {
258	            return "";
259	        }
260	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
261	        if (collapsed.isEmpty()) {
262	            return "";
263	        }
264	        String[] tokens = collapsed.split(" ");
265	        StringBuilder sb = new StringBuilder(collapsed.length());
266	        for (int i = 0; i < tokens.length; i++) {
267	            if (i > 0) {
268	                sb.append(' ');
269	            }
270	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
271	        }
272	        return sb.toString();
273	    }
274	
275	    /**
276	     * Resolve and normalize the owner's postal address, preferring the structured form.
277	     *
278	     * <p>When a non-blank {@code addressLine1} is supplied the structured form is used: it, and the
279	     * optional {@code addressLine2}, are normalized in place and the composed address is the
280	     * normalized addressLine1 with a single space and the normalized addressLine2 appended when
281	     * addressLine2 is present. Otherwise the flat {@code address} input is normalized. Returns
282	     * {@code null} when neither form yields a non-empty address, so the caller can reject the
283	     * request.
284	     */
285	    private String composeAddress(Owner owner) {
286	        String line1 = owner.getAddressLine1();
287	        if (line1 != null && !line1.isBlank()) {
288	            String normalizedLine1 = normalizeAddress(line1);
289	            owner.setAddressLine1(normalizedLine1);
290	            String line2 = owner.getAddressLine2();
291	            if (line2 != null && !line2.isBlank()) {
292	                String normalizedLine2 = normalizeAddress(line2);
293	                owner.setAddressLine2(normalizedLine2);
294	                return normalizedLine1 + " " + normalizedLine2;
295	            }
296	            owner.setAddressLine2(null);
297	            return normalizedLine1.isEmpty() ? null : normalizedLine1;
298	        }
299	        String normalized = normalizeAddress(owner.getAddress());
300	        return normalized.isEmpty() ? null : normalized;
301	    }
302	
303	    /**
304	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
305	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
306	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
307	     */
308	    private static String normalizeForHousehold(String value) {
309	        if (value == null) {
310	            return "";
311	        }
312	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
313	    }
314	
315	    /**
316	     * Return the owners that already share this owner's household, i.e. resolve to the same
317	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
318	     * postcode).
319	     */
320	    private List<Owner> householdMembers(Owner owner) {
321	        String householdId = householdIdFor(owner);
322	        List<Owner> members = new java.util.ArrayList<>();
323	        for (Owner existing : this.clinicService.findAllOwners()) {
324	            if (existing.isDeleted()) {
325	                continue;
326	            }
327	            if (householdId.equals(householdIdFor(existing))) {
328	                members.add(existing);
329	            }
330	        }
331	        return members;
332	    }
333	
334	    /**
335	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
336	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
337	     */
338	    private boolean sharesHouseholdWithExisting(Owner owner) {
339	        return !householdMembers(owner).isEmpty();
340	    }
341	
342	    /**
343	     * Count the existing owners that share this owner's first name and last name, compared
344	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
345	     */
346	    private int namesakeCount(Owner owner) {
347	        String firstName = owner.getFirstName();
348	        String lastName = owner.getLastName();
349	        int count = 0;
350	        for (Owner existing : this.clinicService.findAllOwners()) {
351	            if (firstName != null && lastName != null
352	                && firstName.equalsIgnoreCase(existing.getFirstName())
353	                && lastName.equalsIgnoreCase(existing.getLastName())) {
354	                count++;
355	            }
356	        }
357	        return count;
358	    }
359	
360	    /**
361	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
362	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes an empty string).
363	     * Because it is a pure function of the last name and postcode, every owner in the same household
364	     * deterministically resolves to the same value.
365	     */
366	    private static String householdIdFor(Owner owner) {
367	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
368	        String key = normalizeForHousehold(owner.getLastName()) + "|" + postcode;
369	        try {
370	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
371	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
372	            StringBuilder sb = new StringBuilder(12);
373	            for (int i = 0; i < 6; i++) {
374	                sb.append(String.format("%02X", digest[i]));
375	            }
376	            return sb.toString();
377	        }
378	        catch (java.security.NoSuchAlgorithmException e) {
379	            throw new IllegalStateException(e);
380	        }
381	    }
382	
383	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
384	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
385	        "NSW", new int[] {2000, 2099},
386	        "VIC", new int[] {3000, 3099},
387	        "QLD", new int[] {4000, 4099});
388	
389	    /**
390	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
391	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
392	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
393	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
394	     * postcode.
395	     */
396	    private boolean isPostcodeValid(Owner owner) {
397	        String postcode = owner.getPostcode();
398	        if (postcode == null || postcode.isEmpty()) {
399	            return true;
400	        }
401	        if (!postcode.matches("\\d{4}")) {
402	            return false;
403	        }
404	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
405	        if (range == null) {
406	            return true;
407	        }
408	        int value = Integer.parseInt(postcode);
409	        return value >= range[0] && value <= range[1];
410	    }
411	
412	    /**
413	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
414	     * "possible duplicate": one that shares the owner's last name (case-insensitive) and postcode
415	     * but carries a different (normalized) telephone. When several match, the one with the smallest
416	     * id is chosen so the result is deterministic. Returns {@code null} when the owner has no
417	     * postcode or no such existing owner exists.
418	     */
419	    private Owner possibleDuplicateOf(Owner owner) {
420	        String lastName = owner.getLastName();
421	        String postcode = owner.getPostcode();
422	        String telephone = owner.getTelephone();
423	        if (lastName == null || postcode == null || postcode.isEmpty()) {
424	            return null;
425	        }
426	        Owner match = null;
427	        for (Owner existing : this.clinicService.findAllOwners()) {
428	            if (lastName.equalsIgnoreCase(existing.getLastName())
429	                && postcode.equals(existing.getPostcode())
430	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
431	                if (match == null || (existing.getId() != null && match.getId() != null
432	                    && existing.getId() < match.getId())) {
433	                    match = existing;
434	                }
435	            }
436	        }
437	        return match;
438	    }
439	
440	    /** Maximum number of owners permitted in a single city. */
441	    private static final int CITY_CAPACITY = 50;
442	
443	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
444	    private static final int DAILY_CREATE_LIMIT = 100;
445	
446	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
447	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
448	
449	    /**
450	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
451	     * Used to enforce the per-city capacity on create (before this owner is saved).
452	     */
453	    private int cityOwnerCount(Owner owner) {
454	        String city = owner.getCity();
455	        int count = 0;
456	        for (Owner existing : this.clinicService.findAllOwners()) {
457	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
458	                count++;
459	            }
460	        }
461	        return count;
462	    }
463	
464	    /** Fixed public holidays the business-day roll skips. */
465	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
466	        java.time.LocalDate.parse("2026-01-01"),
467	        java.time.LocalDate.parse("2026-01-26"),
468	        java.time.LocalDate.parse("2026-04-25"),
469	        java.time.LocalDate.parse("2026-12-25"),
470	        java.time.LocalDate.parse("2026-12-28"));
471	
472	    /**
473	     * Roll a registration date forward onto a business day: any Saturday, Sunday or listed public
474	     * holiday is advanced one day at a time until a non-holiday weekday is reached; a date that is
475	     * already a non-holiday weekday is returned unchanged. Applied to the effective registration date
476	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
477	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
478	     */
479	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
480	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
481	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
482	            || PUBLIC_HOLIDAYS.contains(date)) {
483	            date = date.plusDays(1);
484	        }
485	        return date;
486	    }
487	
488	    /**
489	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
490	     * per-day create limit on create (before this owner is saved).
491	     */
492	    private int ownersRegisteredOn(java.time.LocalDate day) {
493	        int count = 0;
494	        for (Owner existing : this.clinicService.findAllOwners()) {
495	            if (day.equals(existing.getRegistrationDate())) {
496	                count++;
497	            }
498	        }
499	        return count;
500	    }
501	
502	    /**
503	     * The {@code Idempotency-Key} header of the request currently being handled, or {@code null} when
504	     * the header is absent, blank or no servlet request is bound to the calling thread. The generated
505	     * {@link OwnersApi#addOwner} signature carries no header parameter, so it is read from the bound
506	     * request context.
507	     */
508	    private static String currentIdempotencyKey() {
509	        org.springframework.web.context.request.RequestAttributes attrs =
510	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
511	        if (attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs) {
512	            String key = servletAttrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
513	            if (key != null && !key.isBlank()) {
514	                return key;
515	            }
516	        }
517	        return null;
518	    }
519	
520	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
521	    @Override
522	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
523	        HttpHeaders headers = new HttpHeaders();
524	        // Idempotent create: when this request carries an Idempotency-Key we have already seen, return
525	        // the owner originally created for that key (200) instead of creating a duplicate.
526	        String idempotencyKey = currentIdempotencyKey();
527	        if (idempotencyKey != null) {
528	            Integer existingId = idempotentCreates.get(idempotencyKey);
529	            if (existingId != null) {
530	                Owner existing = this.clinicService.findOwnerById(existingId);
531	                if (existing != null) {
532	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
533	                }
534	            }
535	        }
536	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
537	        if (!isPostcodeValid(owner)) {
538	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
539	        }
540	        String telephone = toE164(owner.getTelephone());
541	        if (telephone == null || !hasValidNationalLength(telephone)) {
542	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
543	        }
544	        if (!normalizeEmail(owner)) {
545	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
546	        }
547	        String address = composeAddress(owner);
548	        if (address == null) {
549	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
550	        }
551	        owner.setAddress(address);
552	        owner.setTelephone(telephone);
553	        if (owner.getRegistrationDate() != null
554	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
555	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
556	        }
557	        java.time.LocalDate registrationDate = toBusinessDay(
558	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
559	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
560	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
561	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
562	        }
563	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
564	            return new ResponseEntity<>(HttpStatus.CONFLICT);
565	        }
566	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
567	        // owners with the same last name and postcode automatically share it. The link is no longer
568	        // created by copying an existing owner's id around.
569	        owner.setHouseholdId(householdIdFor(owner));
570	        List<Owner> householdMembers = householdMembers(owner);
571	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
572	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
573	
574	        // Hard duplicate: a new owner whose WHOLE identityKey (telephone|email|householdId) equals an
575	        // existing owner's is a byte-for-byte identity match and is always rejected.
576	        String identityKey = owner.getIdentityKey();
577	        for (Owner existing : this.clinicService.findAllOwners()) {
578	            if (existing.isDeleted()) {
579	                continue;
580	            }
581	            if (identityKey.equals(existing.getIdentityKey())) {
582	                return new ResponseEntity<>(HttpStatus.CONFLICT);
583	            }
584	        }
585	        // Household member: another owner already shares this (last name, postcode) household. This
586	        // is no longer rejected as a duplicate — an exact byte-for-byte identity match is already
587	        // caught above, and a distinct additional household member is admitted with its membership
588	        // level capped (see below) at one above the current household maximum. The 'sharesHousehold'
589	        // flag now only signals that the caller vouches for the member, suppressing the
590	        // possible-duplicate flagging below.
591	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner that
592	        // shares an existing owner's last name and postcode with a different telephone.
593	        if (declaredHouseholdMember) {
594	            owner.setPossibleDuplicate(false);
595	            owner.setPossibleDuplicateOf(null);
596	        }
597	        else {
598	            Owner duplicateOf = possibleDuplicateOf(owner);
599	            owner.setPossibleDuplicate(duplicateOf != null);
600	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
601	        }
602	        owner.setNamesakeCount(namesakeCount(owner));
603	        owner.setHouseholdSize(householdMembers.size() + 1);
604	        // Level ceiling: a new owner's membershipLevel cannot exceed one above the current maximum
605	        // membershipLevel among their existing household members. With no existing member, no cap.
606	        if (householdMembers.isEmpty()) {
607	            owner.setMembershipLevelCap(null);
608	        }
609	        else {
610	            int maxHouseholdLevel = householdMembers.stream()
611	                .mapToInt(member -> ownerMapper.membershipLevel(member))
612	                .max()
613	                .getAsInt();
614	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
615	        }
616	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
617	        owner.setRegistrationDate(registrationDate);
618	        owner.setCustomerCode(customerCodeFor(owner));
619	        this.clinicService.saveOwner(owner);
620	        if (idempotencyKey != null) {
621	            idempotentCreates.put(idempotencyKey, owner.getId());
622	        }
623	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
624	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
625	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
626	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
627	        headers.setLocation(UriComponentsBuilder.newInstance()
628	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
629	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
630	    }
631	
632	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
633	    @Override
634	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
635	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
636	        if (currentOwner == null) {
637	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
638	        }
639	        currentOwner.setAddress(ownerFieldsDto.getAddress());
640	        currentOwner.setCity(ownerFieldsDto.getCity());
641	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
642	        currentOwner.setLastName(ownerFieldsDto.getLastName());
643	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
644	        currentOwner.setEmail(ownerFieldsDto.getEmail());
645	        if (!normalizeEmail(currentOwner)) {
646	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
647	        }
648	        this.clinicService.saveOwner(currentOwner);
649	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
650	    }
651	
652	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
653	    @Transactional
654	    @Override
655	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
656	        Owner owner = this.clinicService.findOwnerById(ownerId);
657	        if (owner == null) {
658	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
659	        }
660	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
661	        owner.setDeleted(true);
662	        this.clinicService.saveOwner(owner);
663	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
664	    }
665	
666	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
667	    @Override
668	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
669	        Owner owner = this.clinicService.findOwnerById(ownerId);
670	        if (owner == null) {
671	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
672	        }
673	        HttpHeaders headers = new HttpHeaders();
674	        Pet pet = petMapper.toPet(petFieldsDto);
675	        owner.setId(ownerId);
676	        pet.setOwner(owner);
677	        pet.getType().setName(null);
678	        this.clinicService.savePet(pet);
679	        PetDto petDto = petMapper.toPetDto(pet);
680	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
681	            .buildAndExpand(pet.getId()).toUri());
682	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
683	    }
684	
685	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
686	    @Override
687	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
688	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
689	        if (currentOwner != null) {
690	            Pet currentPet = this.clinicService.findPetById(petId);
691	            if (currentPet != null) {
692	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
693	                currentPet.setName(petFieldsDto.getName());
694	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
695	                this.clinicService.savePet(currentPet);
696	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
697	            }
698	        }
699	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
700	    }
701	
702	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
703	    @Override
704	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
705	        HttpHeaders headers = new HttpHeaders();
706	        Visit visit = visitMapper.toVisit(visitFieldsDto);
707	        Pet pet = new Pet();
708	        pet.setId(petId);
709	        visit.setPet(pet);
710	        this.clinicService.saveVisit(visit);
711	        VisitDto visitDto = visitMapper.toVisitDto(visit);
712	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
713	            .buildAndExpand(visit.getId()).toUri());
714	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
715	    }
716	
717	
718	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
719	    @Override
720	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
721	        Owner owner = this.clinicService.findOwnerById(ownerId);
722	        if (owner != null) {
723	            Pet pet = owner.getPet(petId);
724	            if (pet != null) {
725	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
726	            }
727	        }
728	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
729	    }
730	}
