190	     * Resolves the region from the owner's 4-digit postcode range, or {@code null}
191	     * when the postcode is absent, malformed, or in no known range.
192	     */
193	    default String regionFromPostcode(Owner owner) {
194	        String postcode = owner.getPostcode();
195	        if (postcode == null) {
196	            return null;
197	        }
198	        int code;
199	        try {
200	            code = Integer.parseInt(postcode.trim());
201	        }
202	        catch (NumberFormatException ex) {
203	            return null;
204	        }
205	        if (code >= 2000 && code <= 2099) {
206	            return "NSW";
207	        }
208	        if (code >= 3000 && code <= 3099) {
209	            return "VIC";
210	        }
211	        if (code >= 4000 && code <= 4099) {
212	            return "QLD";
213	        }
214	        return null;
