243	     * Returns the owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
244	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or
245	     * more points. The derived level is then capped by {@link Owner#getMembershipLevelCap()} when
246	     * present, so a new owner's level cannot exceed one above the highest level in their household.
247	     */
248	    default Integer membershipLevel(Owner owner) {
249	        int points = membershipPoints(owner);
250	        int level;
251	        if (points <= 1) {
252	            level = 1;
253	        }
254	        else if (points <= 3) {
255	            level = 2;
256	        }
257	        else if (points <= 5) {
258	            level = 3;
259	        }
260	        else {
261	            level = 4;
262	        }
263	        Integer cap = owner.getMembershipLevelCap();
264	        if (cap != null && level > cap) {
265	            level = cap;
266	        }
267	        return level;
268	    }
269	
270	    /**
271	     * The owner's tenure in whole elapsed fiscal years: the number of fiscal-year boundaries
272	     * (1 July) crossed between {@code registrationDate} and the current date. A newly created
273	     * owner (registered in the current fiscal year) has zero tenure, and a missing
274	     * registrationDate (e.g. legacy records) is likewise treated as zero.
275	     */
276	    default long tenureFiscalYears(Owner owner) {
277	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
278	        if (registrationDate == null) {
279	            return 0;
280	        }
281	        long years = fiscalYearOf(java.time.LocalDate.now()) - fiscalYearOf(registrationDate);
282	        return Math.max(years, 0);
283	    }
284	
285	    /**
286	     * The fiscal year (a four-digit calendar year) that the given date falls in. The fiscal year
287	     * starts on 1 July and is identified by the calendar year in which it ends, so a date on or
288	     * after 1 July belongs to the fiscal year of the following calendar year.
289	     */
290	    default int fiscalYearOf(java.time.LocalDate date) {
291	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
292	    }
293	
294	    /**
295	     * The owner's fiscal year, formatted 'FY&lt;YY&gt;' where YY is the last two digits of the
296	     * fiscal year of the {@code registrationDate} (which is stored business-day-adjusted). The
297	     * fiscal year starts on 1 July. Returns {@code null} when no registrationDate is recorded.
298	     */
299	    default String fiscalYear(Owner owner) {
300	        if (owner.getRegistrationDate() == null) {
301	            return null;
302	        }
303	        return "FY" + String.format("%02d", fiscalYearOf(owner.getRegistrationDate()) % 100);
304	    }
305	
306	    /**
307	     * Builds the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;'
308	     * where YY is the last two digits of the fiscal year of the (business-day-adjusted)
309	     * registrationDate. Returns {@code null} when either source field is absent.
310	     */
311	    default String membershipNumber(Owner owner) {
312	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
313	            return null;
314	        }
315	        return owner.getCustomerCode() + "-M"
316	            + String.format("%02d", fiscalYearOf(owner.getRegistrationDate()) % 100);
