319	    /**
320	     * Computes a single Luhn check digit (0-9) over the digits contained in the
321	     * owner's customerCode. Non-digit characters are ignored. Returns {@code null}
322	     * when the customerCode is absent.
323	     */
324	    default Integer checkDigit(Owner owner) {
325	        String customerCode = owner.getCustomerCode();
326	        if (customerCode == null) {
327	            return null;
328	        }
329	        int sum = 0;
330	        boolean dbl = true;
331	        for (int i = customerCode.length() - 1; i >= 0; i--) {
332	            char c = customerCode.charAt(i);
333	            if (c < '0' || c > '9') {
334	                continue;
335	            }
336	            int d = c - '0';
337	            if (dbl) {
338	                d *= 2;
339	                if (d > 9) {
340	                    d -= 9;
341	                }
342	            }
343	            sum += d;
344	            dbl = !dbl;
345	        }
346	        return (10 - (sum % 10)) % 10;
347	    }
